import { ColumnDef, Row } from '@tanstack/react-table';
import BillIcon from '@/components/icons/BillIcon';
import ViewIcon from '@/components/icons/ViewIcon';
import { Link } from 'react-router-dom';
import { SalaryList } from '../../types/salary.types';

function fmtSalary(n: number | undefined | null) {
    if (n === undefined || n === null || Number.isNaN(Number(n))) {
        return '—';
    }
    return Number(n).toLocaleString('en-US', { maximumFractionDigits: 2 });
}

// Create a separate component for the actions cell
const ActionsCell = ({ row }: { row: Row<SalaryList> }) => {
    return (
        <div className="flex flex-row justify-center gap-6">
            <BillIcon className="cursor-pointer" />
            <Link to={`/human-resources/salaries-details/${row.original.id}`}>
                <ViewIcon className="cursor-pointer text-primery-blue-400" />
            </Link>
        </div>
    );
};

export const columns: ColumnDef<SalaryList>[] = [
    {
        accessorKey: 'name',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    اسم الموظف
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                {row.original.name}
            </div>
        ),
    },
    {
        accessorKey: 'basic_salary',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    الراتب الأساسي
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                {fmtSalary(row.original.basic_salary)}
            </div>
        ),
    },
    {
        accessorKey: 'total_allowances',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    البدلات والحوافز
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                {fmtSalary(row.original.total_allowances)}
            </div>
        ),
    },
    {
        accessorKey: 'total_deductions',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    الخصومات
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                {fmtSalary(row.original.total_deductions)}
            </div>
        ),
    },
    {
        accessorKey: 'total_rewards',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    المكافآت
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                {fmtSalary(row.original.total_rewards)}
            </div>
        ),
    },
    {
        accessorKey: 'total_salary',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    صافي الراتب
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                {fmtSalary(row.original.total_salary)}
            </div>
        ),
    },
    {
        accessorKey: 'month',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    تاريخ الاستحقاق
                </div>
            );
        },
        cell: ({ row }) => {
            const m = row.original.month;
            const y = row.original.year;
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {m && y ? `${String(m).padStart(2, '0')}/${y}` : '—'}
                </div>
            );
        },
    },
    {
        id: 'payment_status',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    حالة الدفع
                </div>
            );
        },
        cell: () => {
            return (
                <div className="text-xs text-[#625E74] font-medium tracking-normal leading-[115%]">
                    <p className="border border-white-blue-300 p-1 w-fit rounded-sm">غير متاح</p>
                </div>
            );
        },
    },
    {
        id: 'actions',
        header: () => {
            return (
                <div className="text-sm text-center px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    الإجراءات
                </div>
            );
        },
        cell: ({ row }) => <ActionsCell row={row} />,
    },
];
