import { Table } from '@tanstack/react-table';
import { Input } from '@/components/ui/input';
import SearchIcon from '@/components/icons/Search';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import ArrowBackIcon from '@/components/icons/ArrowBackIcon';
import { CustomSelect } from '@/components/dropDown/Dropdown';
import { Filters } from '@/types/table.types';
import { SalaryList } from '../../types/salary.types';
import AddDeduction from '@/features/payroll-allowances/components/payrollList/AddDeduction';
import { useState } from 'react';
import { PlusIcon } from 'lucide-react';
import AddAllowancePopup from './AddAllowancePopup';

const MONTH_OPTIONS = Array.from({ length: 12 }, (_, i) => ({
    label: String(i + 1),
    value: String(i + 1),
}));

function buildYearOptions(centerYear: number) {
    const years: { label: string; value: string }[] = [];
    for (let y = centerYear - 5; y <= centerYear + 5; y++) {
        years.push({ label: String(y), value: String(y) });
    }
    return years;
}

export interface SalariesDataTableToolbarProps {
    table: Table<SalaryList>;
    globalFilter: string;
    setGlobalFilter: (value: string) => void;
    filters: Filters;
    setFilters: (value: Filters) => void;
    handleRefreshTable?: () => void;
    data?: SalaryList[];
    payrollMonth: number;
    payrollYear: number;
    onPayrollMonthYearChange: (month: number, year: number) => void;
}

export function DataTableToolbar({
    globalFilter,
    setGlobalFilter,
    filters,
    setFilters,
    handleRefreshTable,
    payrollMonth,
    payrollYear,
    onPayrollMonthYearChange,
}: SalariesDataTableToolbarProps) {
    const [addDeduction, setAddDeduction] = useState(false);
    const [addAllowance, setAddAllowance] = useState(false);
    const yearOptions = buildYearOptions(payrollYear);

    return (
        <>
            <div className="flex flex-col p-2 sm:flex-row sm:items-center sm:justify-between gap-3">
                <UnderlineHeading text="قائمة الرواتب" />
                <div className="flex flex-col sm:flex-row sm:items-center gap-3 sm:gap-4 flex-wrap">
                    <div className="flex flex-wrap items-center gap-2">
                        <span className="text-sm text-primery-blue-700 whitespace-nowrap">الفترة:</span>
                        <CustomSelect
                            value={String(payrollMonth)}
                            onValueChange={(v) => onPayrollMonthYearChange(Number(v), payrollYear)}
                            placeholder="الشهر"
                            width="min-w-[88px]"
                            options={MONTH_OPTIONS}
                        />
                        <CustomSelect
                            value={String(payrollYear)}
                            onValueChange={(v) => onPayrollMonthYearChange(payrollMonth, Number(v))}
                            placeholder="السنة"
                            width="min-w-[100px]"
                            options={yearOptions}
                        />
                    </div>
                    <div className="flex flex-row items-center w-full sm:w-[287px] border border-white-blue-300 bg-white-blue-50 h-[36px] p-2 rounded-[6px]">
                        <Input
                            placeholder="ابحث باسم الموظف"
                            value={globalFilter}
                            onChange={(event) => setGlobalFilter(event.target.value)}
                            className="text-white-blue-800 p-0 tracking-normal text-xs lg:text-sm lg:leading-[16.8px] border-none outline-none focus-visible:ring-0 placeholder:text-white-blue-800"
                        />
                        <button type="button" className="bg-transparent border-none">
                            <SearchIcon className="text-white-blue-800" />
                        </button>
                    </div>
                    <div className="flex fle-row items-center gap-4">
                        <CustomSelect
                            value={(filters?.status as string) || ''}
                            onValueChange={(value) => {
                                setFilters({ ...filters, status: value });
                            }}
                            placeholder="الحالة"
                            width="min-w-[77px]"
                            options={[
                                { label: 'الحالة', value: '' },
                                { label: 'متاح', value: 'active' },
                                { label: 'غير متاح', value: 'not active' },
                            ]}
                        />
                    </div>
                    <div className="flex items-center justify-center gap-2 flex-wrap">
                        <PrimaryButton
                            onClick={() => setAddDeduction(true)}
                            className="text-base px-[14px] xl:py-2 leading-5 font-semibold font-cairo tracking-normal"
                        >
                            <p className="text-xs tracking-normal font-normal leading-[22.49px]">اضافة خصم</p>
                            <PlusIcon className="text-white-blue-100 w-5 h-5" />
                        </PrimaryButton>
                        <PrimaryButton
                            onClick={() => setAddAllowance(true)}
                            className="text-base px-[6px] xl:py-2 leading-5 font-semibold font-cairo tracking-normal"
                        >
                            <p className="text-xs tracking-normal font-normal leading-[22.49px]">اضافة مكافأة</p>
                            <PlusIcon className="text-white-blue-100 w-5 h-5" />
                        </PrimaryButton>
                    </div>
                    <div className="flex items-center justify-center gap-2 px-[14px] py-2 bg-primery-blue-50 border border-primery-blue-50 shadow-[0px_1px_2px_0px_#1018280D] rounded-lg ">
                        <ArrowBackIcon className="text-primery-blue-700" />
                        <p className="text-xs text-primery-blue-500 tracking-normal font-normal leading-[22.49px]">
                            تصدير
                        </p>
                    </div>
                </div>
            </div>
            <AddDeduction
                open={addDeduction}
                setAddDeduction={setAddDeduction}
                defaultMonth={payrollMonth}
                defaultYear={payrollYear}
                onCreated={handleRefreshTable}
            />
            <AddAllowancePopup
                open={addAllowance}
                setAddAllowance={setAddAllowance}
                onCreated={handleRefreshTable}
                defaultMonth={payrollMonth}
                defaultYear={payrollYear}
            />
        </>
    );
}
